from app.core.resources import display_rows

"""Admission Applications endpoints and their PostgreSQL queries."""

from fastapi import APIRouter, Depends, HTTPException, Query, Request

from app.core import sql_queries as sql
from app.core.resources import staff_only
from app.core.security import require

from .schemas import CreateRequest, UpdateRequest
from .service import Service

TABLE = "admission_applications"
router = APIRouter(prefix="/admission-applications", tags=["Admission Applications"])


# --- PostgreSQL queries for this screen (generated by tools/generate_module_sql.py from the
# live table definitions; regenerate after schema migrations). Values are bound as %(name)s
# parameters, never formatted into the text; app.core.sql_queries runs these statements and
# keeps custom fields (record_extras) with each record. Table names resolve through the
# connection's search_path (EDUNEXA_DB_SCHEMA).

LIST_SQL = """
SELECT t.code,
       t.program_code,
       t.academic_year_code,
       t.first_name,
       t.last_name,
       t.email,
       t.phone,
       t.applied_on,
       t.status,
       t.student_code,
       t.enquiry_code,
       t.cycle_code,
       t.source_code,
       t.date_of_birth,
       t.gender,
       t.admission_category,
       t.address,
       t.consent_at,
       t.submitted_at,
       t.assigned_employee_code,
       t.submitted_by_user_code,
       x.data AS extras
FROM admission_applications AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'admission_applications' AND x.record_code = t.code
ORDER BY t.code
"""

GET_SQL = """
SELECT t.code,
       t.program_code,
       t.academic_year_code,
       t.first_name,
       t.last_name,
       t.email,
       t.phone,
       t.applied_on,
       t.status,
       t.student_code,
       t.enquiry_code,
       t.cycle_code,
       t.source_code,
       t.date_of_birth,
       t.gender,
       t.admission_category,
       t.address,
       t.consent_at,
       t.submitted_at,
       t.assigned_employee_code,
       t.submitted_by_user_code,
       x.data AS extras
FROM admission_applications AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'admission_applications' AND x.record_code = t.code
WHERE t.code = %(code)s
"""

INSERT_SQL = """
INSERT INTO admission_applications (
    code,
    program_code,
    academic_year_code,
    first_name,
    last_name,
    email,
    phone,
    applied_on,
    status,
    student_code,
    enquiry_code,
    cycle_code,
    source_code,
    date_of_birth,
    gender,
    admission_category,
    address,
    consent_at,
    submitted_at,
    assigned_employee_code,
    submitted_by_user_code
)
VALUES (
    %(code)s,
    %(program_code)s,
    %(academic_year_code)s,
    %(first_name)s,
    %(last_name)s,
    %(email)s,
    %(phone)s,
    %(applied_on)s,
    %(status)s,
    %(student_code)s,
    %(enquiry_code)s,
    %(cycle_code)s,
    %(source_code)s,
    %(date_of_birth)s,
    %(gender)s,
    COALESCE(%(admission_category)s, 'regular'::text),
    COALESCE(%(address)s, '{}'::jsonb),
    %(consent_at)s,
    %(submitted_at)s,
    %(assigned_employee_code)s,
    %(submitted_by_user_code)s
)
"""

UPDATE_SQL = """
UPDATE admission_applications
SET program_code = %(program_code)s,
    academic_year_code = %(academic_year_code)s,
    first_name = %(first_name)s,
    last_name = %(last_name)s,
    email = %(email)s,
    phone = %(phone)s,
    applied_on = %(applied_on)s,
    status = %(status)s,
    student_code = %(student_code)s,
    enquiry_code = %(enquiry_code)s,
    cycle_code = %(cycle_code)s,
    source_code = %(source_code)s,
    date_of_birth = %(date_of_birth)s,
    gender = %(gender)s,
    admission_category = %(admission_category)s,
    address = %(address)s,
    consent_at = %(consent_at)s,
    submitted_at = %(submitted_at)s,
    assigned_employee_code = %(assigned_employee_code)s,
    submitted_by_user_code = %(submitted_by_user_code)s
WHERE code = %(code)s
"""

DELETE_SQL = """
DELETE FROM admission_applications
WHERE code = %(code)s
"""

REFERENCED_BY_SQL = """
SELECT CASE
    WHEN EXISTS (SELECT 1 FROM admission_documents WHERE application_code = %(code)s) THEN 'admission_documents'
    WHEN EXISTS (SELECT 1 FROM admission_enrollment_events WHERE application_code = %(code)s) THEN 'admission_enrollment_events'
    WHEN EXISTS (SELECT 1 FROM admission_offers WHERE application_code = %(code)s) THEN 'admission_offers'
    WHEN EXISTS (SELECT 1 FROM admission_reviews WHERE application_code = %(code)s) THEN 'admission_reviews'
    WHEN EXISTS (SELECT 1 FROM admission_status_history WHERE application_code = %(code)s) THEN 'admission_status_history'
    WHEN EXISTS (SELECT 1 FROM application_guardians WHERE application_code = %(code)s) THEN 'application_guardians'
    WHEN EXISTS (SELECT 1 FROM application_qualifications WHERE application_code = %(code)s) THEN 'application_qualifications'
    WHEN EXISTS (SELECT 1 FROM students WHERE admission_application_code = %(code)s) THEN 'students'
END AS referenced_by
"""
# --- end of generated SQL


def query_list(data):
    return sql.fetch_all(data, TABLE, LIST_SQL)


def query_get(data, code):
    record = sql.fetch_one(data, TABLE, GET_SQL, code)
    if record is None:
        raise HTTPException(404, "Record not found")
    return record


def query_save(data, record):
    return sql.save(data, TABLE, record, INSERT_SQL, UPDATE_SQL)


def query_delete(data, code):
    sql.delete(data, TABLE, DELETE_SQL, code)


def query_referenced_by(data, code):
    return sql.referenced_by(data, TABLE, REFERENCED_BY_SQL, code)


class Queries:
    table = TABLE
    list = staticmethod(query_list)
    get = staticmethod(query_get)
    save = staticmethod(query_save)
    delete = staticmethod(query_delete)
    referenced_by = staticmethod(query_referenced_by)


service = Service(Queries())


@router.get("")
def list_records(
    request: Request,
    offset: int = Query(0, ge=0),
    limit: int = Query(50, ge=1, le=200),
    user=Depends(require(TABLE, "view")),
):
    staff_only(user)
    data = request.app.state.store.snapshot()
    records = display_rows(data, TABLE, query_list(data))
    return {
        "items": records[offset : offset + limit],
        "total": len(records),
        "offset": offset,
        "limit": limit,
    }


@router.get("/{code}")
def get_record(code: str, request: Request, user=Depends(require(TABLE, "view"))):
    staff_only(user)
    return query_get(request.app.state.store.snapshot(), code)


@router.post("", status_code=201)
def create_record(
    body: CreateRequest, request: Request, user=Depends(require(TABLE, "create"))
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        return service.create(
            data, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.patch("/{code}")
def update_record(
    code: str,
    body: UpdateRequest,
    request: Request,
    user=Depends(require(TABLE, "edit")),
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        return service.update(
            data, code, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.delete("/{code}", status_code=204)
def delete_record(code: str, request: Request, user=Depends(require(TABLE, "delete"))):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        service.delete(data, code, user["code"])
